    """Check the categorical expectations for the given batch and summary. It checks if the number of distinct values and the percentage of distinct values are below the threshold. If so, it expects the column values to be in the set of value counts without NaN.

    :param name: str. The name of the column.
    :param summary: dict. The summary of the column.
    :param batch: Any. The batch of data to be checked.
    :param *args: Any. Additional arguments.
    :return: Tuple[str, dict, Any]. The name, summary, and batch.
    ```
    """
    if summary["n_distinct"] > summary["n"]:
        raise ValueError(
            f"The number of distinct values ({summary['n_distinct']}) is greater than the number of values ({summary['n']}) in column '{name}'."
        )

    if summary["n_missing"] > summary["n"]:
        raise ValueError(
            f"The number of missing values ({summary['n_missing']}) is greater than the number of values ({summary['n']}) in column '{name}'."
        )

    if summary.get("n_unique") is not None and summary["n_unique"] < summary["n_distinct"]:
        raise ValueError(
            f"The number of unique values ({summary['n_unique']}) is less than the number of distinct values ({summary['n_distinct']}) in column '{name}'."
        )

    if (
        summary["n_missing"] / summary["n"] > 0.5
        or summary["n_distinct"] / summary["n"] > 0.5
    ):
        raise ValueError(
            f"The number of missing values ({summary['n_missing']}) or the number of distinct values ({summary['n_distinct']}) is greater than 50% of the number of values ({summary['n']}) in column '{name}'."
        )

    if summary["n_missing"]:
        batch = batch.dropna()

    if summary["n_distinct"] > 100:
        raise ValueError(
            f"The number of distinct values ({summary['n_distinct']}) is greater than 100 in column '{name}'."
        )

    if summary["n_distinct"] > 10 and summary["n_distinct"] / summary["n"] > 0.9:
        raise ValueError(
            f"The number of distinct values ({summary['n_distinct']}) is greater than 90% of the number of values ({summary['n']}) in column '{name}'."
        )

    if summary["n"] > 100000:
        raise ValueError(
            f"The number of values ({summary['n']}) is greater than 100000 in column '{name}'."
        )

    if summary["n_distinct"] == 1:
        raise ValueError(
            f"The number of distinct values ({summary['n_distinct']}) is 1 in column '{name}'."
        )

    if summary["n_distinct"] == 2:
        if summary["p_distinct"][0] > 0.95 or summary["p_distinct"][1] > 0.95:
            raise ValueError(
                f"The percentage of distinct values ({summary['p_distinct'][0]}) or ({summary['p_distinct'][1]}) is greater than 95% in column '{name}'."
            )

    return name, summary, batch

"""Sort the column names of the given dictionary in ascending or descending order based on the input parameter. If the sort parameter is None, the original dictionary is returned.

:param dct: Dict. The input dictionary to be sorted.
:param sort: Optional string. The sorting order. It can be "ascending", "descending" or None.
:return: Dict. The sorted dictionary.
"""
