    print("Invalid unit type: {}".format(unit_type))
    return

if unit_type == "regex":
    try:
        regex = self.interpreter.interpret_regex(unit_name)
    except Exception as e:
        print(e)
        return

    try:
        self.interpreter.unhide_regex(regex)
    except Exception as e:
        print(e)
        return

    print(
        "Unit {} with regular expression {} was successfully unhidden.".format(
            unit_type, unit_name
        )
    )

elif unit_type == "regex_group":
    try:
        regex_group_name = self.interpreter.interpret_regex_group(unit_name)
    except Exception as e:
        print(e)
        return

    try:
        self.interpeter.unhide_regex_group(regex_group_name)
    except Exception as e:
        print(e)
        return

    print(
        "Unit {} with name {} was successfully unhidden.".format(
            unit_type, unit_name
        )
    )

elif unit_type in self.valid_unit_types:
    try:
        self.interpreter.unhide_unit(unit_type, unit_name)
    except Exception as e:
        print(e)
        return

    print(
        "Unit {} with name '{}' was successfully unhidden.".format(
            unit_type, unit_name
