:param axis: None or int or tuple of ints, optional. Axis or axes along which a sum is performed. The default, axis=None, will sum all of the elements of the input array.
:param keepdims: bool, default: False. If this is set to True, the axes which are reduced are left in the result as dimensions with size one.
:param random_state: int or RandomState, optional. Controls the randomness of the algorithm.
:param accountant: BudgetAccountant, optional. Accountant to keep track of privacy budget.
:param **unused_args: Should warn the user if any other parameters are passed.
:return: ndarray. Returns a new array containing the quantile values.
"""
# Check random state
if random_state is not None:
    random_state = check_random_state(random_state)

# Check array
array = np.asarray(array)
if array.ndim == 0:
    raise ValueError("array must be at least 1-dimensional")

# Check quant
quant = np.asarray(quant)
if quant.ndim == 0:
    quant = quant[None]
if not np.all((0 <= quant) & (quant <= 1)):
    raise ValueError("quant must be in the unit interval [0, 1]")

# Check bounds
if bounds is not None:
    if len(bounds) != 2:
        raise ValueError("bounds must be a tuple of length 2")
    bounds = np.asarray(bounds)
    if not np.all(bounds[0] <= bounds[1]):
        raise ValueError("bounds must be a tuple of length 2, where bounds[0] <= bounds[1]")

# Ravel array
array = array.ravel()

# Check accountant
if accountant is not None:
    accountant.check_privacy_budget(epsilon)

# Check axis
if axis is not None:
    if np.isscalar(axis):
        axis = (axis,)
    axis = tuple(axis)
    if len(axis) > array.ndim:
        raise ValueError("axis is out of bounds")
    if any(a < 0 for a in axis):
        raise ValueError("axis must be non-negative")
    if any(a >= array.ndim for a in axis):
        raise ValueError("axis must be smaller than the number of array dimensions")

# Calculate quantile
if bounds is not None:
    quantile_func = partial(np.quantile, q=quant, axis=axis, keepdims=keepdims, method='inverted_cdf')
    return quantile_func(bounds[0] + (bounds[1] - bounds[0]) * array)
else:
    quantile_func = partial(np.quantile, q=quant, axis=axis, keepdims=keepdims, interpolation='linear')
    return quantile_func(array)

