"""This function clips the examples of a 2-dimensional array to given bounds. It checks if the input array is a numpy array, then it checks the bounds and clips the array accordingly. It first checks that the bounds are indeed tuple and that shape is an integer. If these conditions are not met, the function raises a error of type. It then extracts the lower and upper bounds, ensuring they are in the correct format and adjusting them to be arrays of the specified data type (dtype). The function enforces that the lower and upper bounds must be of the same shape and dimensionality, specifically either scalar or 1-dimensional arrays.

:param array: np.ndarray. The array to be clipped. After clipping, all examples have a 2-norm of at most `clip`.
:param bounds: tuple. The bounds of the form (min, max) which the array is to be clipped to. `min` and `max` must be scalar, unless the array is 2-dimensional.
:return: np.ndarray. The clipped array.
"""
import numpy as np

if not isinstance(array, np.ndarray):
    raise TypeError("The array must be a numpy array.")

if not isinstance(bounds, tuple) or len(bounds) != 2:
    raise TypeError("The bounds must be a tuple of length 2.")

if not isinstance(bounds[0], (int, float)) or not isinstance(bounds[1], (int, float)):
    raise TypeError("The bounds must be scalar.")

if len(array.shape) == 1:
    lower_bound = np.array([bounds[0]])
    upper_bound = np.array([bounds[1]])
else:
    lower_bound = np.array(bounds[0])
    upper_bound = np.array(bounds[1])

if len(lower_bound.shape) != 1 or len(upper_bound.shape) != 1:
    raise TypeError("The bounds must be 1-dimensional arrays.")

if lower_bound.shape != upper_bound.shape:
    raise ValueError("The lower and upper bounds must have the same shape.")

if len(lower_bound.shape) == 2:
    if lower_bound.shape[1] != 1:
        raise ValueError("The lower bound must be a column vector.")
    if upper_bound.shape[1] != 1:
        raise ValueError("The upper bound must be a column vector.")

if len(lower_bound.shape) == 1:
    if lower_bound.shape[0] != 1:
        raise ValueError("The lower bound must be a row vector.")
    if upper_bound.shape[0] != 1:
        raise ValueError("The upper bound must be a row vector.")

return np.clip(array, lower_bound, upper_bound)

