"""This function searches for repeated patterns in a given password and returns information about the matches found. It uses regular expressions to find both greedy and lazy matches of repeated substrings in the password. It then compares the lengths of the greedy and lazy matches to determine the base token and calculates the repeat count. Finally, it recursively matches and scores the base string to get additional information about the matches.

:param password: String. The password to search for repeated patterns.
:param _ranked_dictionaries: List of dictionaries. A list of ranked dictionaries used for matching. Defaults to RANKED_DICTIONARIES.
:return: List of dictionaries. A list of dictionaries containing information about the repeated matches found in the password. Each dictionary includes the pattern type, start and end indices of the match, the matched token, the base token, the number of guesses required to guess the base token, the sequence of matches for the base token, and the repeat count.
"""
matches = []
# Find greedy matches
for dictionary in _ranked_dictionaries:
    for regex in dictionary["regexes"]:
        for match in re.finditer(regex, password):
            if match.end() - match.start() < 3:
                continue
            base_token = match.group()
            greedy_match = match
            lazy_match = re.search(
                rf"{re.escape(base_token)}+", password, re.IGNORECASE
            )
            if not lazy_match:
                continue
            if lazy_match.start() < greedy_match.start():
                continue
            repeat_count = (greedy_match.end() - greedy_match.start()) // (
                lazy_match.end() - lazy_match.start()
            )
            if repeat_count < 2:
                continue
            matches.append(
                {
                    "pattern": dictionary["pattern"],
                    "i": greedy_match.start(),
                    "j": greedy_match.end(),
                    "token": base_token,
                    "base_token": base_token,
                    "base_token_length": len(base_token),
                    "guesses": dictionary["guesses"],
                    "matches": [
                        {
                            "i": lazy_match.start(),
                            "j": lazy_match.end(),
                            "token": base_token,
                            "guesses": dictionary["guesses"],
                            "base_token": base_token,
                            "base_token_length": len(base_token),
                            "repeat_count": repeat_count,
                        }
                    ],
                    "repeat_count": repeat_count,
                }
            )
# Find lazy matches
for dictionary in _ranked_dictionaries:
    for regex in dictionary["regexes"]:
        for match in re.search(
            rf"{regex}+", password, re.IGNORECASE
        ).finditer():
            if match.end() - match.start() < 3:
                continue
            base_token = match.group()
            lazy_match = match
            greedy_match = re.search(
                rf"{re.escape(base_token)}+", password, re.IGNORECAse
            )
            if not greedy_match:
                continue
            if greedy_match.start() < lazy_match.start():
                continue
            repeat_count = (lazy_match.end() - lazy_match.start()) // (
                greedy_match.end() - greedy_match.start()
            )
            if repeat_count < 2:
                continue
            matches.append(
                {
                    'pattern': dictionary['pattern'],
                    'i': lazy_match.start(),
                    'j': lazy_match.end(),
                    'token': base_token,
                    'base_token': base_token,
                    'base_token_length': len(base_token),
                    'guesses': dictionary['guesses'],
                    'matches': [
                        {
                            'i': greedy_match.start(),
                            'j': greedy_match.end(),
                            'token': base_token,
                            'guesses': dictionary['guesses'],
                            'base_token': base_token,
                            'base_token_length': len(base_token),
                            'repeat_count': repeat_count
                        }
                    ],
                    'repeat_count': repeat_count
                }
            )
# Recursively match and score the base token
for match in matches:
    base_token = match['base_token']
    base_token_length = match['base_token_length']
    repeat_count = match['repeat_count']
    for i in range(0, len(password) - base_token_length * repeat_count + 1):
        j = i + base_token_length * repeat_count
        if password[i:j] == base_token * repeat_count:
            match['matches'].append({
                'i': i,
                'j': j,
                'token': base_token,
                'guesses': match['guesses'],
                'base_token': base_token,
                'base_token_length': base_token_length,
                'repeat_count': repeat_count
            })
return match

