"""This function takes an HRP (Human Readable Part), data, and a specification as input and computes a Bech32 string. It combines the data with a checksum generated and returns the Bech32 string.

:param hrp: String. The Human Readable Part of the Bech32 string.
:param data: List of integers. The data values to be encoded.
:param spec: String. The specification to be used for encoding.
:return: String. The computed Bech32 string.
"""
if not isinstance(hrp, str):
    raise TypeError("Expected hrp to be str, got {}".format(type(hrp)))
if not isinstance(data, list):
    raise TypeError("Expected data to be list, got {}".format(type(data)))
if not isinstance(spec, str):
    raise TypeError("Expected spec to be str, got {}".format(type(spec)))
if not hrp:
    raise ValueError("Expected hrp to be non-empty")
if not data:
    raise ValueError("Expected data to be non-empty")
if not spec:
    raise ValueError("Expected spec to be non-empty")
if not (len(spec) == 32 or len(spec) == 5):
    raise ValueError("Expected spec to be of length 32 or 5, got {}".format(len(spec)))
if not all(isinstance(x, int) for x in data):
    raise TypeError("Expected all data values to be int, got {}".format(type(data[0])))
if not all(0 <= x < 32 for x in data):
    raise ValueError("Expected all data values to be between 0 and 31, got {}".format(data[0]))
if not all(0 <= x < 32 for x in spec):
    raise ValueError("Expected all spec values to be between 0 and 31, got {}".format(spec[0]))
if not hrp.islower():
    raise ValueError("Expected hrp to be lowercase, got {}".format(hrp))
if not hrp.isalnum():
    raise ValueError("Expected hrp to be alphanumeric, got {}".format(hrp))
if not hrp.startswith("bc"):
    raise ValueError("Expected hrp to start with 'bc', got {}".format(hrp))
if not hrp.endswith("1"):
    raise ValueError("Expected hrp to end with '1', got {}".format(hrp))
if len(hrp) > 83:
    raise ValueError("Expected hrp to be at most 83 characters, got {}".format(len(hrp)))
if len(data) > 63:
    raise ValueError("Expected data to be at most 63 values, got {}".format(len(data)))
if len(spec) == 5:
    spec = [0] * 5 + spec
hrp_bytes = hrp.encode("utf-8")
data_bytes = bytes(data)
spec_bytes = bytes(spec)
hrp_bytes = hrp_bytes + b"1"
hrp_bytes = hrp_bytes + b"\x00" * (6 - len(hrp_bytes) % 6)
data_bytes = data_bytes + b"\x00" * (8 - len(data_bytes) % 8)
spec_bytes = spec_bytes + b"\x00" * (8 - len(spec_bytes) % 8)
hrp_bytes = hrp_bytes + data_bytes
hrp_bytes = hrp_bytes + spec_bytes
hrp_bytes = hrp_bytes + b"\x00" * (8 - len(hrp_bytes) % 8)
hrp_bytes = hrp_bytes + spec_bytes
hrp_bytes = hrp_bytes + b"\x30" * (8 - len(spec_bytes) % 8)
hrp_bytes = hrp_bytes + spec_bytes
hrp_bytes = hrp

