"""
url = ""
if self.scheme:
    url += self.scheme + ":"
if self.authority:
    url += "//" + self.authority
if self.path:
    url += self.path
if self.query:
    url += "?" + self.query
if self.fragment:
    url += "#" + self.fragment
if full_quote:
    url = quote(url)
return url

